INSERT INTO `web_corporatereports` (`id`, `title`, `description`, `doc`, `created_at`) VALUES
(2, 'Results - Financial Results For The Period 31.12.2024', '<p>Submission of Unaudited Standalone and Consolidated Financial Results for the quarter and nine months ended 31st December, 2024.</p><p><strong>05 Feb, 2025 | 02:57pm</strong></p>', 'REPORT_20250520042357_955.pdf', '2025-04-05 16:11:07'),
(3, 'Announcement under Regulation 30 (LODR) -Meeting Updates', '<p>Submission of outcome of Board Meeting approving the proposal to expand capacity of various plants and setting up of captive solar power plant</p>', 'REPORT_20250520042105_846.pdf', '2025-04-05 16:11:21'),
(4, 'Board Meeting Intimation for Approval And Consideration Of Audited Financial Results', '<p>Gallantt Ispat Ltdhas informed BSE that the meeting of the Board of Directors of the Company is scheduled on 21/05/2025 ,inter alia, to consider and approve Audited Financial Results for the quarter and year ended 31st March, 2025, Audited Annual Accounts of the Company, Recommendation of Final Dividend, if any, and other matters</p>', 'REPORT_20250520041656_351.pdf', '2025-05-08 14:24:11'),
(5, 'Six-monthly environmental compliance report of stipulated conditions of environmental clearance (April, 2025 to September, 2025)', '<p>This Six-Monthly Environmental Compliance Report (April 2025 - September 2025) is submitted by <strong>Gallantt Ispat Limited</strong> in compliance with the Environmental Clearance conditions issued by the <strong>Ministry of Environment, Forest &amp; Climate Change (MoEF&amp;CC)</strong>. The report covers the expansion of the Integrated Steel Plant at <strong>GIDA Industrial Area, Gorakhpur (U.P.)</strong>, and includes details of environmental monitoring such as ambient air quality, stack emissions, noise levels, and ground water quality, demonstrating adherence to applicable statutory norms and environmental safeguards.</p>', 'REPORT_20260121112547_986.pdf', '2026-01-21 11:25:47'),
(6, 'Environmental Clearance (EC) Report  issued by the Ministry of Environment, Forest & Climate Change (MoEF&CC).', '<p><strong>Environmental Compliance Report</strong> of <strong>Gallantt Ispat Limited</strong>, submitted in accordance with the Environmental Clearance conditions of the <strong>Ministry of Environment, Forest &amp; Climate Change (MoEF&amp;CC)</strong>. It covers the expansion of the Integrated Steel Plant at <strong>GIDA, Gorakhpur (U.P.)</strong> and includes environmental compliance and monitoring details in line with statutory requirements.</p>', 'REPORT_20260121115121_417.pdf', '2026-01-21 11:51:21');
