INSERT INTO `web_jobs` (`job_id`, `job_title`, `department`, `experience`, `job_type`, `location`, `vacancies`, `job_description`, `date_posted`, `status`) VALUES
(1, 'Institutional Sales Manager', 'Steel', '7 Yrs', 'Full-Time', 'Uttar Pradesh', 1, '<p><strong>Roles and Responsibilities</strong><br>&nbsp;</p><ul><li>Develop and execute sales strategies to achieve revenue targets through effective government liaison, tender management, and project marketing.<br>&nbsp;</li><li>Build strong relationships with key decision-makers in government agencies, PSUs, and other institutions to identify business opportunities.<br>&nbsp;</li><li>Manage a team of sales professionals to drive institutional sales growth across various sectors such as education, healthcare, infrastructure development projects.<br>&nbsp;</li><li>Collaborate with cross-functional teams (marketing, operations) to develop targeted campaigns for government tenders and projects.<br>&nbsp;</li><li>Analyze market trends and competitor activity to stay ahead in the competitive institutional landscape.</li></ul>', '2025-05-27 12:32:07', 'active'),
(2, 'SAP FICO Consultant - S/4HANA Public Cloud', 'Steel', '4-10 Years', 'Full-Time', 'Uttar Pradesh', 1, '<p>Job Summary:<br>We are looking for a skilled SAP FICO Consultant with hands-on experience in SAP S/4HANA<br>Public Cloud to support projects. The ideal candidate should have strong expertise in core<br>FICO modules (GL, AP, AR, AA, Bank, Cost Center Accounting, Internal Orders, etc.) and a<br>solid understanding of public cloud restrictions, best practices, and standard scope.</p><p>Key Responsibilities:<br>- Implement and support SAP FICO modules in S/4HANA Public Cloud.<br>- Configure and maintain standard scope items such as:<br>o 1GA (Accounts Receivable)<br>o 1KZ (Accounts Payable)<br>o 1KE (Cost Center Accounting)<br>o J59 (Asset Accounting)<br>o 1JD (Bank Account Management), etc.<br>- Collaborate with business stakeholders to gather and analyze finance &amp; controlling<br>requirements.<br>- Handle configuration through SSCUI (Self-Service Configuration UI) and CBC (Central<br>Business Configuration).<br>- Support Fit-to-Standard workshops and drive standardization as per SAP Activate<br>methodology.<br>- Conduct testing (unit, integration, and UAT) and support cutover &amp; go-live activities.<br>- Coordinate with SAP support (SAP Incident Management) for issues or<br>enhancements beyond the standard scope.<br>- Provide post-go-live support and user training.</p><p>Required Skills:<br>- Proven experience in SAP S/4HANA Public Cloud FICO implementation or support.<br>- Good understanding of SAP Best Practices and standard scope items in public cloud.<br>- Experience with SSCUI configuration, Business Process Monitoring, and CBC tools.<br>- Strong knowledge of core FICO areas:<br>o General Ledger, AR, AP, Bank Accounting, Asset Accounting<br>o Cost Center, Profit Center, Internal Order<br>- Basic understanding of integration with other modules: MM, SD, PS, etc.<br>- Knowledge of cloud limitations (no custom code, restricted configuration options,<br>etc.)<br>-Familiarity with BADI extensions, Key User Extensibility, and Output Management.</p><p>Preferred Qualifications:<br>- SAP Certification in S/4HANA Public Cloud - Finance<br>- Exposure to SAP Business Technology Platform (BTP) and public cloud extensibility<br>options<br>- Hands-on with Fiori apps, SAP Analytics Cloud, and public cloud reporting tools</p><p>Soft Skills:<br>- Strong communication and stakeholder management skills<br>- Self-driven with ability to work in a fast-paced public cloud environment<br>- Team player with proactive attitude towards problem solving</p><p>What We Offer:<br>- A challenging and rewarding work environment.<br>- Opportunity to lead significant technological initiatives.<br>- Competitive salary and benefits package.<br>- Career growth and development opportunities.<br>- Accommodation in the Plant Township</p>', '2025-09-10 04:06:57', 'active');
INSERT INTO `web_mediagallery` (`id`, `media_name`, `section`, `category`, `description`, `media_image`, `media_type`, `date_of_post`, `last_update`, `status`, `media_file`, `media_file_type`) VALUES
(1, 'Dealer Trip', 'Life at Gallantt', 'Event', '<p>Moments from our Almaty dealer tour - where partnerships grow stronger through shared experiences, cultural discovery, and the spirit of the Gallantt family.</p>', 'MEDIA_20250520090404_664.jpg', 'image', '2025-04-05', '2026-07-02 07:59:43', 'live', NULL, NULL),
(2, 'Marathon Race', 'Life at Gallantt', 'Event', '<p>Gallantt Group employees came together in stride and spirit, participating in a marathon that celebrated fitness, unity, and our shared commitment to a stronger tomorrow.</p>', 'MEDIA_20250520091102_612.jpeg', 'image', '2025-04-05', '2025-05-20 14:11:02', 'live', NULL, NULL),
(3, 'Almaty Tour', 'Life at Gallantt', 'Event', '<p>Moments from our Almaty dealer tour - where partnerships grow stronger through shared experiences, cultural discovery, and the spirit of the Gallantt family.</p>', 'MEDIA_20250520090527_202.jpeg', 'image', '2025-04-05', '2025-09-13 05:46:00', 'live', NULL, NULL),
(4, 'Baba Ramdev Fecilitation', 'Corporate Highlights', 'Stories', '<p>Gallantt Group\'s CMD, Shri C.P. Agarwal, warmly felicitated Baba Ramdev at his residence in Gorakhpur â€” a moment of mutual respect and shared values.</p>', 'MEDIA_20250520092443_203.jpeg', 'image', '2025-04-14', '2026-07-02 07:45:25', 'live', NULL, NULL),
(5, 'Architect & Engineer Meet', 'Corporate Highlights', 'Event', '<p>Gallantt Group\'s 2025 Architect &amp; Engineer Meet in Gorakhpur brought together industry experts for a day of innovation, collaboration, and future-focused conversations in construction.</p>', 'MEDIA_20250520092807_117.jpg', 'image', '2025-05-07', '2025-07-30 10:39:52', 'live', NULL, NULL),
(6, 'Vice President fecilitation ', 'Corporate Highlights', 'News', '<p>Gallantt Groupâ€™s CMD, Shri C.P. Agarwal, had the honour of felicitating the Honâ€™ble Vice President of India, Shri Jagdeep Dhankhar â€” a proud moment of respect and recognition.</p>', 'MEDIA_20250520092041_240.jpeg', 'image', '2025-03-01', '2025-07-30 10:38:23', 'live', NULL, NULL),
(7, 'ABP Ideas of India', 'Corporate Highlights', 'News', '<p>Mr. Mayank Agarwal, CEO of Gallantt Group, engaged in a thought-provoking fireside chat with Chetan Bhagat at ABP Ideas of India 2025, Grand Hyatt Mumbai - sharing leadership insights and future vision.</p>', 'MEDIA_20250520095006_948.jpg', '', '2025-04-10', '2025-07-30 10:20:52', 'live', NULL, NULL),
(8, 'ABP Ideas of India', 'Corporate Highlights', 'Event', '<p>Mr. Mayank Agarwal, CEO of Gallantt Group, recieveing award at ABP Ideas of India 2025, Grand Hyatt Mumbai</p>', 'MEDIA_20250520095715_901.jpg', 'image', '2025-05-10', '2025-09-13 05:13:47', 'live', NULL, NULL),
(9, 'Gallantt Auditorium Inauguration ', 'Corporate Highlights', 'Foundation', '<p>Gallantt Auditorium at Mahayogi Gorakhnath University was inaugurated by Hon\'ble President Droupadi Murmu, marking a milestone in educational infrastructure.</p>', 'MEDIA_IMG_20250710062857_336.jpeg', 'image', '2025-07-10', '2025-09-13 05:46:25', 'live', NULL, NULL),
(10, 'Gallantt Auditorium Opening Ceremony ', 'Corporate Highlights', 'Foundation', '<p>Gallantt Auditorium at Mahayogi Gorakhnath University was inaugurated by Hon\'ble President Droupadi Murmu, marking a milestone in educational infrastructure.</p>', 'MEDIA_IMG_20250710063106_580.jpeg', 'image', '2025-07-10', '2025-09-13 05:45:03', 'live', NULL, NULL),
(11, 'Gallantt Auditorium Showcasing', 'Corporate Highlights', 'Event', '<p>Gallantt Auditorium at Mahayogi Gorakhnath University was inaugurated by Hon\'ble President Droupadi Murmu, marking a milestone in educational infrastructure.</p>', 'MEDIA_IMG_20250710063208_305.jpeg', 'image', '2025-07-10', '2025-09-13 06:20:22', 'live', NULL, NULL),
(12, 'Gallantt TMT & Cement Dealers/Partners Award Ceremony 2025 in Singapore.', 'Corporate Highlights', 'Event', '<p>Event graciously led by our CMO,<strong> Mr. Prakhar Agrawal</strong>, as we celebrated the strength of our valued partnerships.</p>', 'MEDIA_IMG_20250913061337_735.jpeg', 'image', '2025-09-13', '2025-09-13 06:13:37', 'live', NULL, NULL),
(17, 'Gallantt Group Q1 FY2025â€“26 Results Interview | Insights with CEO Mayank Agarwal on Zee Business', 'Corporate Highlights', 'News', '<p>Catch the full conversation as our CEO, Mr. Mayank Agarwal, joins Anil Singhvi, Chief Business Editor at Zee Business, to present <strong>Gallantt Groupâ€™s Q1 FY2025â€“26 performance</strong> and share insights on the companyâ€™s future growth strategy.</p><p>ðŸ“Š A strategic conversation on <strong>results, resilience, and the road ahead.</strong></p><p>ðŸŽ¥ <a href=\"https://youtu.be/5dtFoi4oZ8c?si=ES_o5Rl0CLZdrQHX\">Watch Now on YouTube</a></p>', 'MEDIA_IMG_20251105042901_235.png', 'image', '2025-11-05', '2025-11-05 04:29:22', 'disabled', NULL, NULL),
(18, 'Gallantt Group Q1 FY2025–26 Results Interview | Insights with CEO Mayank Agarwal on Zee Business', 'Corporate Highlights', 'News', '<p>Catch the full conversation as our CEO, Mr. Mayank Agarwal, joins Anil Singhvi, Chief Business Editor at Zee Business, to present Gallantt Group’s Q1 FY2025–26 performance and share insights on the company’s future growth strategy.</p><p>📊 A strategic conversation on results, resilience, and the road ahead.</p><p>🎥 <a href=\"https://youtu.be/5dtFoi4oZ8c?si=ES_o5Rl0CLZdrQHX\">Watch Now on YouTube</a></p><figure class=\"media\"><oembed url=\"https://youtu.be/5dtFoi4oZ8c?si=RcAGIKZitEyXZRow\"></oembed></figure>', 'MEDIA_IMG_20251105053306_288.png', 'image', '2025-07-30', '2026-07-02 07:56:58', 'live', NULL, NULL),
(19, '   Gallantt Ispat Q2 FY2025–26 Results Interview | Insights with CEO Mayank Agarwal on ET Now', 'Corporate Highlights', 'News', '<p>Gallantt Ispat CEO Mr. Mayank Agarwal joins ET Now to discuss the company’s strong Q2 FY2025–26 performance, reporting a 78% year-on-year profit growth and a significant improvement in EBITDA margins by 45%.</p><p>He highlights key growth drivers including higher production in sponge iron and pellets, reduced raw material costs, and enhanced operational efficiency.</p><p>Mr. Agarwal also unveils a ₹2,250 crore Capex plan focused on steelmaking, solar power, and mining, with upcoming mines in Uttar Pradesh and Rajasthan aimed at strengthening long-term profitability.</p><p>📈 A deep dive into growth, efficiency, and expansion — shaping Gallantt Ispat’s next phase of progress.</p><p>🎥 <a href=\"https://youtu.be/oVPV0IbQ6VM?si=eJ531hn594I4IbGw\">Watch Full Interview on YouTube</a></p>', 'MEDIA_IMG_20251105052719_818.png', 'image', '2025-11-04', '2026-07-02 07:55:11', 'live', NULL, NULL),
(20, 'उड़ान Celebrating 16 Years of Excellence | Gallantt Group Foundation Day', 'Corporate Highlights', 'Event', '<blockquote><p><strong>Gallantt Group proudly presents </strong><i><strong>उड़ान</strong></i><strong> ✨</strong></p><h3><strong>Celebrating 16 Years of Excellence ✨</strong></h3><p>Join us <strong>LIVE</strong> as we celebrate our <strong>Foundation Day</strong>—a journey of <strong>शक्ति | सफलता | संकल्प</strong> 💪</p><p><strong>📅 Date:</strong> 13th November 2025 (Thursday)<br><strong>⏰ Time:</strong> 4:00 PM – 9:00 PM</p><p><strong>📍 Watch Live on our Official Channels:</strong><br>&nbsp;</p><p>🌟 <strong>Facebook</strong>: <a href=\"https://www.facebook.com/share/1K2CVT1TVr/\">Watch Here</a><br>🌟 <strong>YouTube</strong>: <a href=\"https://youtube.com/@gallantt_group?si=84nP3V3Uyp-5ycvn\">Watch Here</a></p><p>Let\'s come together to witness the remarkable journey of growth, excellence, and inspiration that defines <strong>Gallantt Group!</strong> 🌾🏗️</p><p>#GallanttGroup #FoundationDay #Udaan #16YearsOfExcellence #GallanttLive #TeamGallantt #CelebratingSuccess</p></blockquote>', 'MEDIA_IMG_20251112034211_469.png', 'image', '2025-11-12', '2026-07-02 07:51:21', 'live', NULL, NULL),
(21, 'Gallantt Ispat Limited Certified for Network & Web Application Security', 'Corporate Highlights', 'News', '<p><strong>Gallantt Ispat Limited</strong> has <strong>successfully completed its Annual Third-Party Network and Web Application Vulnerability Assessment &amp; Penetration Testing (VAPT) in January 2026</strong>. The assessment confirms that Gallanttâ€™s digital infrastructure is hardened against unauthorized access and emerging cyber threats, reinforcing our commitment to secure, resilient, and reliable digital operations.</p>', 'MEDIA_IMG_20260130062918_172.png', 'image', '2026-01-30', '2026-01-30 06:32:50', 'disabled', NULL, NULL);
